function initPageInteractions() {
  const nav = document.querySelector(".site-nav"),
    toggle = document.querySelector(".menu-toggle"),
    backdrop = document.querySelector(".nav-backdrop");
  const current = location.pathname.split("/").pop() || "index.html";
  nav
    .querySelectorAll("a")
    .forEach((link) =>
      link.classList.toggle(
        "is-current",
        link.getAttribute("href") === current,
      ),
    );
  const setMenu = (open) => {
    nav.classList.toggle("is-open", open);
    backdrop.classList.toggle("is-visible", open);
    toggle.setAttribute("aria-expanded", open);
  };
  toggle.addEventListener("click", () =>
    setMenu(!nav.classList.contains("is-open")),
  );
  backdrop.addEventListener("click", () => setMenu(false));
  nav
    .querySelectorAll("a")
    .forEach((link) => link.addEventListener("click", () => setMenu(false)));
  const observer = new IntersectionObserver(
    (entries) =>
      entries.forEach((entry) => {
        if (entry.isIntersecting) entry.target.classList.add("is-visible");
      }),
    { threshold: 0.15 },
  );
  document
    .querySelectorAll(".info-block,.page-stats div")
    .forEach((item) => observer.observe(item));
  const projectGallery = document.querySelector("[data-project-gallery]");
  if (projectGallery) {
    const cards = [...projectGallery.querySelectorAll("[data-project-card]")];
    const search = projectGallery.querySelector("[data-project-search]");
    const typeFilter = projectGallery.querySelector("[data-project-type]");
    const count = projectGallery.querySelector("[data-project-count]");
    const empty = projectGallery.querySelector("[data-project-empty]");
    let statusFilter = "all";
    const applyProjectFilters = () => {
      const query = search.value.trim().toLocaleLowerCase();
      const type = typeFilter.value;
      let visible = 0;
      cards.forEach((card) => {
        const matchesSearch = !query || card.dataset.search.toLocaleLowerCase().includes(query);
        const matchesStatus = statusFilter === "all" || card.dataset.status === statusFilter;
        const matchesType = type === "all" || card.dataset.type === type;
        const isVisible = matchesSearch && matchesStatus && matchesType;
        card.hidden = !isVisible;
        if (isVisible) visible += 1;
      });
      count.textContent = visible;
      empty.hidden = visible > 0;
      projectGallery.querySelector("[data-project-note]").textContent = visible === cards.length ? "يعرض الآن كامل القائمة" : "نتيجة مطابقة للفلاتر الحالية";
    };
    search.addEventListener("input", applyProjectFilters);
    typeFilter.addEventListener("change", applyProjectFilters);
    projectGallery.querySelectorAll("[data-filter-status]").forEach((button) => button.addEventListener("click", () => {
      statusFilter = button.dataset.filterStatus;
      projectGallery.querySelectorAll("[data-filter-status]").forEach((item) => item.classList.toggle("is-active", item === button));
      applyProjectFilters();
    }));
  }
  document.querySelectorAll(".about-collection-tab").forEach((tab) => {
    tab.addEventListener("click", () => {
      const collection = tab.dataset.collection;
      document
        .querySelectorAll(".about-collection-tab")
        .forEach((item) => item.classList.toggle("is-active", item === tab));
      document
        .querySelectorAll(".about-collection-panel")
        .forEach((panel) =>
          panel.classList.toggle("is-active", panel.dataset.panel === collection),
        );
    });
  });
  const lightbox = document.querySelector(".about-lightbox");
  if (lightbox) {
    const lightboxImage = lightbox.querySelector("img");
    const lightboxLabel = lightbox.querySelector("p");
    document.querySelectorAll("[data-lightbox-src]").forEach((trigger) => {
      trigger.addEventListener("click", () => {
        lightboxImage.src = trigger.dataset.lightboxSrc;
        lightboxImage.alt = trigger.dataset.lightboxLabel;
        lightboxLabel.textContent = trigger.dataset.lightboxLabel;
        lightbox.showModal();
      });
    });
    lightbox.querySelector(".about-lightbox-close").addEventListener("click", () => lightbox.close());
    lightbox.addEventListener("click", (event) => {
      if (event.target === lightbox) lightbox.close();
    });
  }
  const form = document.querySelector(".page-form");
  if (form)
    form.addEventListener("submit", (event) => {
      event.preventDefault();
      form.querySelector(".form-status").textContent =
        "تم استلام طلبك، وسيتواصل معك فريقنا قريبًا.";
      form.reset();
    });
}
function applySavedSiteConfig() {
  try {
    const saved = JSON.parse(
      localStorage.getItem("maskanSiteConfigV1") || "null",
    );
    const company = saved?.company || {};
    const companyName = company.name || "مسكن الكيان للمقاولات";
    Object.values(pageData).forEach((page) => {
      page.intro = page.intro.replace("مسكن الكيان للمقاولات", companyName);
    });
    if (pageData.about)
      pageData.about.intro = company.about || pageData.about.intro;
    if (pageData.contact) {
      pageData.contact.stats[0][0] =
        company.address?.split("،")[0] || pageData.contact.stats[0][0];
      pageData.contact.cards[0][2] =
        company.address || pageData.contact.cards[0][2];
      pageData.contact.cards[2][2] =
        [company.phone, company.email].filter(Boolean).join(" · ") ||
        pageData.contact.cards[2][2];
    }
    const metrics = company.metrics || company;
    document.querySelectorAll("[data-metric]").forEach((element) => {
      if (
        metrics[element.dataset.metric] !== undefined &&
        metrics[element.dataset.metric] !== ""
      ) {
        element.textContent = metrics[element.dataset.metric];
      }
    });
    if (Array.isArray(saved?.services) && saved.services.length) {
      pageData.services.cards = saved.services.map((service, index) => [
        ["▦", "⌂", "✦", "◇"][index % 4],
        service.name,
        service.description,
      ]);
    }
    const savedProjects = JSON.parse(
      localStorage.getItem("maskanProjectsV1") || "null",
    );
    if (
      Array.isArray(savedProjects) &&
      savedProjects.length &&
      pageData.projects
    ) {
      pageData.projects.cards = savedProjects
        .slice(0, 6)
        .map((project, index) => [
          ["⌂", "◈", "✦", "◇"][index % 4],
          project.name,
          `${project.location || "الموقع غير محدد"} · ${project.status || "قيد التنفيذ"}`,
        ]);
    }
    Object.entries(saved?.pages || {}).forEach(([key, content]) => {
      if (!pageData[key]) return;
      if (content.title) pageData[key].title = content.title;
      if (content.description) pageData[key].intro = content.description;
    });
  } catch (error) {
    console.warn("تعذر تحميل إعدادات الموقع المحفوظة", error);
  }
}
applySavedSiteConfig();
const current = document.body.dataset.page;
if (current) renderPage(current);
